from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.tc import tc_helpers
from taf.ul.sc.perf.messenger.messenger import Messenger


def send_email_to_tester(subject=None, user_message=None, receivers=[],
                         generate_default_body=False, message_type="html"):
    """
    Send email to tester.

    :param subject: Email subject
    :param user_message: Message provided by user
    :param receivers: list of receivers. Could be login or full email address
    :param generate_default_body: Generate default body - info about test case and test line
    :param message_type: html or text
    :return: nothing
    """

    msg = Messenger(subject=subject, receivers=receivers)
    if generate_default_body:
        test_line_status = tc_helpers.get_test_line_status()
        msg_content = msg.generate_html_message_content(user_message=user_message, **test_line_status)
        my_msg = msg.prepare_message(html_msg_content=msg_content)
    else:
        if message_type == "html":
            my_msg = msg.prepare_message(html_msg_content=user_message)
        elif message_type == "text":
            my_msg = msg.prepare_message(text_msg_content=user_message)

    msg.send_message(my_msg)


def get_receivers_for_recovery():
    receivers = set()
    if tc.test_line_maintainers:
        if isinstance(tc.test_line_maintainers, list):
            receivers.update(tc.test_line_maintainers)
        else:
            receivers.update(tc.test_line_maintainers.split(";"))

    receivers.update(get_receivers_for_test_results())

    return list(receivers)


def get_receivers_for_test_results():
    receivers = set()
    if tc.tester_username:
        receivers.add(tc.tester_username)
    if tc.test_line_owner:
        receivers.add(tc.test_line_owner)

    return list(receivers)
